1. function calculate(s) {
2.   let stack = [], num = 0, sign = '+';
3.   for (let i = 0; i <= s.length; i++) {
4.     let char = s[i];
5.     if (isDigit(char)) num = num * 10 + parseInt(char);
6.     if (isOp(char) || i === s.length) {
7.       if (sign === '+') stack.push(num);
8.       if (sign === '-') stack.push(-num);
9.       if (sign === '*') stack.push(stack.pop() * num);
10.      if (sign === '/') stack.push(Math.trunc(stack.pop() / num));
11.      sign = char; num = 0;
12.    }
13.  }
14.  return stack.reduce((a, b) => a + b, 0);
15. }
